import itertools

def solve_for_n(n):
    min_max_sum = float('inf')
    for a in itertools.product([1, -1], repeat=n):
        max_abs_sum = 0
        # We want to find a subsequence t_1, ..., t_k such that t_{i+1}-t_i <= 2
        # This can be solved using dynamic programming.
        # dp[i] = set of all possible sums using a subsequence ending at index i
        # such that the gap condition is satisfied.
        # But wait, the condition is only for i=1 to k-1.
        # So we can pick any t_1.

        # Let dp[i] = set of all possible sums of a valid subsequence ending at index i.
        # A subsequence is valid if t_{j+1}-t_j <= 2.
        # The first element t_1 can be any index.

        dp = [set() for _ in range(n)]
        for i in range(n):
            dp[i].add(a[i])
            for j in [i-1, i-2]:
                if j >= 0:
                    for s in dp[j]:
                        dp[i].add(s + a[i])

        max_val_for_a = 0
        for i in range(n):
            for s in dp[i]:
                max_val_for_a = max(max_val_for_a, abs(s))

        min_max_sum = min(min_max_sum, max_val_for_a)
    return min_max_sum

