def max_abs_sum_bitmask(n, a):
    # dp[i] is the bitmask of sums in the subsequence ending at index i
    # dp[i] = (1 << (a[i] + n)) | (dp[i-1] << a[i]) | (dp[i-2] << a[i])
    # where the shift is 1 or -1.
    dp = [0] * n
    mask = (1 << (2 * n + 1)) - 1
    max_abs = 0
    for i in range(n):
        val = a[i]
        dp[i] = (1 << (val + n))
        if i >= 1:
            if val == 1:
                dp[i] |= (dp[i-1] << 1)
            else:
                dp[i] |= (dp[i-1] >> 1)
        if i >= 2:
            if val == 1:
                dp[i] |= (dp[i-2] << 1)
            else:
                dp[i] |= (dp[i-2] >> 1)
        dp[i] &= mask

        # To find the max absolute sum, we check the bits in dp[i]
        # The bits are from 0 to 2n. The sum s is at bit s+n.
        # We want to find max |s| for s such that (dp[i] >> (s+n)) & 1.
        # Let's just check all s from -n to n.
        for s in range(-n, n + 1):
            if (dp[i] >> (s + n)) & 1:
                if abs(s) > max_abs:
                    max_abs = abs(s)
    return max_abs

