import time

def solve_fast(n):
    min_max_sum = float('inf')
    for a in itertools.product([1, -1], repeat=n):
        dp = [0] * n
        mask = (1 << (2 * n + 1)) - 1
        max_abs_a = 0
        for i in range(n):
            val = a[i]
            dp[i] = (1 << (val + n))
            if i >= 1:
                if val == 1: dp[i] |= (dp[i-1] << 1)
                else: dp[i] |= (dp[i-1] >> 1)
            if i >= 2:
                if val == 1: dp[i] |= (dp[i-2] << 1)
                else: dp[i] |= (dp[i-2] >> 1)
            dp[i] &= mask

            if dp[i] > 0:
                high_bit = dp[i].bit_length() - 1
                s_high = high_bit - n
                low_bit = (dp[i] & -dp[i]).bit_length() - 1
                s_low = low_bit - n
                max_abs_a = max(max_abs_a, abs(s_high), abs(s_low))

        if max_abs_a < min_max_sum:
            min_max_sum = max_abs_a
    return min_max_sum

